create or replace view public.registry_missing_artist_intake_queue with (security_invoker = true) as with missing as (select legacy_slug, count(distinct relationship_id)::integer as affected_relationship_count, count(*) filter (where missing_side = 'source')::integer as missing_source_count, count(*) filter (where missing_side = 'target')::integer as missing_target_count, array_agg(distinct relationship_type order by relationship_type) as relationship_types from public.registry_relationship_endpoint_work_queue where endpoint_work_state = 'missing_entity' and missing_entity_type = 'artist' group by legacy_slug) select m.legacy_slug, initcap(replace(m.legacy_slug, '-', ' ')) as suggested_display_name, m.affected_relationship_count, m.missing_source_count, m.missing_target_count, m.relationship_types, s.submission_id, s.submission_review_status, s.submission_created_at, s.submission_reviewed_at, case when s.submission_id is null then 'needs_intake' when s.submission_review_status in ('rejected','archived','merged') then 'needs_reassessment' when s.submission_review_status in ('accepted_as_memory','accepted_as_evidence','accepted_as_relationship_context') then 'review_completed' else 'intake_in_progress' end as intake_state from missing m left join public.registry_missing_artist_latest_submission s using (legacy_slug);;
